    "cardCss": ".cd-picker-select-wrap,.cd-picker-select-wrap *{box-sizing:border-box}.cd-picker-select-wrap{height:100%;background:#F4F4F4;display:flex;align-items:center;justify-content:center}.cd-picker-select-box{width:64%;height:78px;background:#FFFFFF;border:1px solid #E8E8E8;border-radius:10px;overflow:hidden;position:relative}.cd-picker-select-wheel{animation:cd-picker-select-wheel 8s ease-in-out infinite}.cd-picker-select-opt{height:26px;display:grid;place-items:center;font-size:12px;color:#141414}.cd-picker-select-band{position:absolute;top:26px;left:0;right:0;height:26px;border-top:1px solid #E8E8E8;border-bottom:1px solid #E8E8E8;background:rgba(23,108,91,.06);pointer-events:none}.cd-picker-select-fade{position:absolute;left:0;right:0;height:26px;background:rgba(255,255,255,.62);pointer-events:none}.cd-picker-select-fade-t{top:0}.cd-picker-select-fade-b{bottom:0}@keyframes cd-picker-select-wheel{0%,18%{transform:translateY(0)}23%,41%{transform:translateY(-26px)}46%,64%{transform:translateY(-52px)}69%,87%{transform:translateY(-78px)}92%,100%{transform:translateY(-104px)}}"
